/**
 * The languages assets/daily-plan-copy.js speaks. That module is shared with
 * the website and shipped under a content hash on its pages, so the Mini App
 * does not edit it; it hands it the first language of the reader's chain that
 * it actually has.
 */
const DAILY_COPY_LANGS = Object.freeze(['ru', 'en', 'es', 'de', 'fr', 'zh-Hans', 'ko']);

function dailyLang(lang) {
  return langChain(lang).find((l) => DAILY_COPY_LANGS.indexOf(l) >= 0) || 'ru';
}


/* --------------------------------------------------------------------------
 * Configuration
 * ----------------------------------------------------------------------- */

/* --------------------------------------------------------------------------
 * The two endpoints
 *
 * This used to be one constant and a comment saying a second one must never be
 * added: RU networks reached api.magicesim.store 3/3 and the origin 0/3, so a
 * direct fallback would have been invisible in testing and broken for exactly
 * the customers this app serves.
 *
 * That measurement was taken through a browser on a plain RU connection. The
 * Mini App is not that. It runs inside Telegram's WebView on a phone whose VPN
 * is system-wide, so the WebView's traffic takes the tunnel too — and measured
 * there, on the owner's iPhone on 2026-08-18, the picture inverts:
 *
 *              /health              catalogue 604KB
 *   Render     8/8  p50   237ms     4/4  p50  654ms
 *   Yandex     2/8  p50 12239ms     4/4  p50 1720ms   (AbortError / 502)
 *
 * So for THIS surface the gateway is the fallback, not the road. The storefront
 * keeps the old arrangement, because a browser on a plain connection is still
 * the network the old measurement describes.
 *
 * Both hosts terminate at the same Render backend — /api/v1/status reports the
 * same commit through either — so there is one database, one session table and
 * one set of rules. A token minted through one is valid at the other because it
 * is the same row, and the TMA limiters key on identity (initData fingerprint,
 * telegram user, customer) rather than on IP, so which road it arrives by
 * changes nothing about them.
 * ----------------------------------------------------------------------- */

const API_RENDER = 'https://esim-backend-3wmu.onrender.com';
const API_GATEWAY = 'https://api.magicesim.store';

// Ordered. The client walks this list and stops at the first endpoint that
// returns a VERDICT — not the first that returns success. See shouldFailOver.
const API_ENDPOINTS = [
  { name: 'render', base: API_RENDER },
  { name: 'yandex_fallback', base: API_GATEWAY },
];

// Kept for the storefront and for anything that still expects one base.
const API_BASE = API_GATEWAY;

// The international catalogue: Render only (see globalCatalogue in createApi).
const GLOBAL_CATALOGUE_PATH = '/api/v1/retail/packages?market=global';
const GLOBAL_CATALOGUE_TIMEOUT_MS = 15000;

/** The website's validator when it is loaded (app/index.html loads it), else the same rule inline. */
function validateGlobalCatalogue(status, body) {
  const g = typeof globalThis !== 'undefined' && globalThis.MagicGlobalCatalog;
  if (g && typeof g.validate === 'function') return g.validate(status, body);
  if (status !== 200 || !body || body.market !== 'global' || body.currency !== 'USD' || !Array.isArray(body.data)) {
    return { ok: false, reason: status === 429 ? 'busy' : 'unavailable' };
  }
  const rows = body.data.filter((p) => p && (p.currency === undefined || p.currency === 'USD')
    && (Number(p.price) > 0 || (Array.isArray(p.term_prices) && p.term_prices.some((t) => t && Number(t.price) > 0 && Number(t.days) > 0))));
  if (!rows.length) return { ok: false, reason: 'empty' };
  const A = typeof globalThis !== 'undefined' ? globalThis.MagicAssortment : null;
  const layout = body.assortment && typeof body.assortment === 'object' ? body.assortment : null;
  if (A && typeof A.attach === 'function') A.attach(rows, layout);
  return { ok: true, packages: rows, assortment: layout };
}

/* --------------------------------------------------------------------------
 * The market — MINIAPP-I18N-LEGAL-1 (owner, 2026-10-23)
 *
 * TWO payment markets, chosen by the customer with one compact switch and by
 * nothing else — never by the Telegram language, never by a guess:
 *   ru     — roubles, Platega, SBP and Russian cards, the Russian documents: the
 *            app as it always was, and the DEFAULT for everyone (existing
 *            customers keep buying exactly as before);
 *   global — US dollars from the international catalogue, the English Terms,
 *            Refund Policy and Privacy Policy; online payment is OFF until a
 *            Merchant of Record is connected and the server checks consents.
 * The choice is a display preference kept on the device (localStorage). It
 * decides what the screens SHOW; no order ever trusts it — the server stamps
 * every Russian order `ru` and refuses every GLOBAL one while payments are off.
 * ----------------------------------------------------------------------- */

const MARKETS = Object.freeze(['ru', 'global']);

/** The international website's published legal documents (LEGAL-3) — linked, never copied. */
const INTL_LEGAL_URLS = Object.freeze({
  terms: 'https://magicesim.store/en/terms/',
  refund: 'https://magicesim.store/en/refund/',
  privacy: 'https://magicesim.store/en/privacy/',
});

/*
 * The international checkout's two consents (LEGAL-3, the website's wording and gate, mirrored): the Terms of Service +
 * Refund Policy, and the express request for immediate supply — two boxes, never ticked in advance. A payment may pass
 * only through `globalPayAllowed`: both boxes, both document versions, and payments open. Payments are OFF
 * (GLOBAL_PAYMENTS_OPEN — no Merchant of Record yet, owner); opening them needs the server consent record and the payment
 * adapter in one backend release first (MAGIC_ESIM_LEGAL3_CONSENT_SERVER_PLAN), never this constant alone.
 * The versions are the published documents' (seo/terms-en.mjs, seo/refund-en.mjs — equal by test).
 */
const GLOBAL_PAYMENTS_OPEN = false;
const INTL_LEGAL_VERSIONS = Object.freeze({ terms: '0.9.1 (pre-launch)', refund: '0.9 (pre-launch)' });

/*
 * LEGAL-4: the international documents are published in English and translated into es, de, fr, zh-Hans and ko — each
 * language reads its own /<prefix>/… version, exactly as the website's footer and consent links do (English is the master;
 * Terms §5.6). Russian and English read the English documents. The prefixes are the site's (seo/locales.mjs), by test.
 */
const INTL_LEGAL_PREFIX = Object.freeze({ es: 'es', de: 'de', fr: 'fr', 'zh-Hans': 'zh', ko: 'ko' });
function intlLegalUrls(lang) {
  const prefix = Object.prototype.hasOwnProperty.call(INTL_LEGAL_PREFIX, lang) ? INTL_LEGAL_PREFIX[lang] : null;
  if (!prefix) return INTL_LEGAL_URLS;
  return Object.freeze({
    terms: `https://magicesim.store/${prefix}/terms/`,
    refund: `https://magicesim.store/${prefix}/refund/`,
    privacy: `https://magicesim.store/${prefix}/privacy/`,
  });
}
function globalPayAllowed(c) {
  return !!(c && c.paymentsOpen === true && c.terms === true && c.delivery === true
    && typeof c.termsVersion === 'string' && c.termsVersion !== ''
    && typeof c.refundVersion === 'string' && c.refundVersion !== '');
}
// What a future GLOBAL order request carries — the server checks it again and records it with its own time.
function globalConsentRecord(c) {
  if (!globalPayAllowed(c)) throw new Error('CONSENT_REQUIRED');
  return { terms_version: c.termsVersion, refund_version: c.refundVersion, accepted_terms: true, requested_immediate_supply: true };
}
const MARKET_DEFAULT = 'ru';
const MARKET_KEY = 'mesim.market';

/** The stored market, or the default. An unknown value is dropped, never guessed into one. */
function createMarketStore(storage) {
  const read = () => {
    let raw = null;
    try { raw = storage ? storage.getItem(MARKET_KEY) : null; } catch { return MARKET_DEFAULT; }
    return MARKETS.indexOf(raw) >= 0 ? raw : MARKET_DEFAULT;
  };
  const write = (m) => {
    if (MARKETS.indexOf(m) < 0) return read();
    try { if (storage) storage.setItem(MARKET_KEY, m); } catch { /* a private tab: this session only */ }
    return m;
  };
  return { get: read, set: write };
}

/**
 * A US-dollar amount, formatted as the international website formats it in that language (assets/i18n/<lang>.js
 * `fmt.numberLocale` + `fmt.currencyDisplay`): «$12.99», «USD 12.99», «12,99 USD», «US$12.99». Russian (not a site
 * language) reads «$12.99». Never a conversion: the amount is the server's.
 */
// = the website's `fmt.numberLocale` / `fmt.currencyDisplay` per language (app/core.test.js holds them equal).
const USD_FORMAT = Object.freeze({
  ru: ['en-US', 'symbol'], en: ['en-US', 'symbol'], es: ['es-419', 'symbol'], de: ['de-DE', 'code'],
  fr: ['fr-FR', 'code'], 'zh-Hans': ['zh-Hans', 'symbol'], ko: ['ko', 'symbol'],
});
function usd(amount, lang) {
  if (amount === null || amount === undefined || amount === '') return '';
  const n = Number(amount);
  if (!Number.isFinite(n)) return '';
  const [locale, display] = USD_FORMAT[lang] || USD_FORMAT.en;
  try {
    return new Intl.NumberFormat(locale, { style: 'currency', currency: 'USD', currencyDisplay: display,
      minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
  } catch {
    return `$${n.toFixed(2)}`;
  }
}

// Reads: three attempts total. The first retry catches a dropped connection, the
// second catches a bad few seconds. A third would mostly add latency to an
// outage a human can already see.
const READ_ATTEMPTS = 3;
const READ_BACKOFF_MS = [400, 1200];

// Writes get ONE retry and only when a key makes it safe to repeat.
const WRITE_ATTEMPTS_WITH_KEY = 2;
const WRITE_BACKOFF_MS = [700];

// The session mint gets a read's budget, because the whole app is blocked behind
// it and a cold gateway reliably burns the first attempt. See openSession.
const SESSION_ATTEMPTS = 3;
const SESSION_BACKOFF_MS = [600, 1500];

// Longer than the gateway's own ~12s retry budget would take to exhaust, so a
// slow-but-alive request is not abandoned by the client first; short enough that
// a hung one does not become a spinner nobody can dismiss.
const REQUEST_TIMEOUT_MS = 20000;
// The snapshot is same-origin on a CDN. If it has not answered in this long it
// is not going to, and it must not be allowed to hold the first paint hostage.
const STATIC_CATALOGUE_TIMEOUT_MS = 6000;

/* --------------------------------------------------------------------------
 * Small helpers
 * ----------------------------------------------------------------------- */

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/** Bytes -> GB for display. null stays null: unknown is not zero. */
function gb(bytes) {
  if (bytes === null || bytes === undefined || bytes === '') return null;
  const n = Number(bytes);
  if (!Number.isFinite(n) || n < 0) return null;

  return Math.round((n / (1024 ** 3)) * 100) / 100;
}

/**
 * A price for a Russian customer: whole roubles, grouped, sign after.
 *
 * Non-breaking spaces, written as ESCAPES rather than typed. A price that wraps
 * between its digits — or away from its sign — is a price somebody misreads, and
 * a literal space character in source is invisible in review and easy for an
 * editor to normalise into something else. This started life as U+2009 THIN
 * SPACE, which is breakable in some renderers.
 */
function money(rub) {
  // Absence before coercion, for the third time in this file: Number(null) is 0,
  // so a missing price would render as "0 ₽" — a free eSIM, confidently offered.
  if (rub === null || rub === undefined || rub === '') return '';

  const n = Number(rub);
  if (!Number.isFinite(n)) return '';

  const grouped = Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '\u00A0');

  return `${grouped}\u00A0\u20BD`;
}

/**
 * Days left, floored, never negative.
 *
 * Floored rather than rounded on purpose: telling somebody they have "1 day"
 * when 4 hours remain is the error that gets a customer stranded.
 */
function daysLeft(expiresAt, now = Date.now()) {
  if (!expiresAt) return null;
  const t = new Date(expiresAt).getTime();
  if (!Number.isFinite(t)) return null;

  return Math.max(0, Math.floor((t - now) / 86400000));
}

/**
 * How much of the bundle is left, 0..1, or null when unknown.
 *
 * Returns null — not 0 — when either side is missing, so a progress bar can
 * render "unknown" instead of an empty tank.
 */
function remainingFraction(esim) {
  // `Number(null)` is 0, not NaN — which is exactly how "we could not ask the
  // provider" turns into "you have nothing left". So absence is checked BEFORE
  // coercion, on both sides.
  const rawTotal = esim ? esim.total_gb : null;
  const rawLeft = esim ? esim.remaining_gb : null;
  if (rawTotal === null || rawTotal === undefined || rawTotal === '') return null;
  if (rawLeft === null || rawLeft === undefined || rawLeft === '') return null;

  const total = Number(rawTotal);
  const left = Number(rawLeft);
  if (!Number.isFinite(total) || total <= 0) return null;
  if (!Number.isFinite(left)) return null;

  return Math.max(0, Math.min(1, left / total));
}

